def mark_existing_guides_reviewed(apps, schema_editor):
    """Existing verified knowledge predates the review field.

    Preserve it as approved; newly created records start as drafts until an
    administrator reviews them.
    """
    TroubleshootingGuide = apps.get_model('motor', 'TroubleshootingGuide')
    db_alias = schema_editor.connection.alias
    (
        TroubleshootingGuide.objects.using(db_alias)
        .filter(is_verified=True)
        .update(review_status='approved')
    )


def unmark_existing_guides(apps, schema_editor):
    TroubleshootingGuide = apps.get_model('motor', 'TroubleshootingGuide')
    db_alias = schema_editor.connection.alias
    TroubleshootingGuide.objects.using(db_alias).update(review_status='draft')


